import numpy as np
import time

def circle_packing21() -> np.ndarray:
    '''
    Places 21 non-overlapping circles inside a rectangle of
    perimeter 4, maximizing the sum of their radii.

    Returns:
        circles: numpy array of shape (21, 3), where each row
            stores (x, y, radius).
    '''
    n = 21
    sqrt3 = np.sqrt(3.0)
    start_time = time.time()
    time_limit = 600.0

    def capacity(W, H, r, start_with_long):
        if r <= 0 or W <= 2*r - 1e-15 or H <= 2*r - 1e-15:
            return 0
        R = int(np.floor(1.0 + max(0.0, (H - 2.0 * r) / (sqrt3 * r))))
        total = 0
        for k in range(R):
            is_long = (k % 2 == 0) if start_with_long else (k % 2 == 1)
            s = r if is_long else 2.0 * r
            y = r + k * sqrt3 * r
            if s > W - r + 1e-15:
                continue
            span = (W - r) - s
            ncols = int(np.floor(span / (2.0 * r) + 1.0 + 1e-12))
            total += max(0, ncols)
        return total

    def binary_search_r(W, H, start_with_long, need=n):
        lo, hi = 0.0, 0.5 * min(W, H) - 1e-12
        if hi <= 0:
            return 0.0
        for _ in range(50):
            mid = 0.5 * (lo + hi)
            if capacity(W, H, mid, start_with_long) >= need:
                lo = mid
            else:
                hi = mid
        return lo

    def build_hex_centers(W, H, r, start_with_long, limit=n):
        centers = []
        y0 = r
        for k in range(100):
            is_long = (k % 2 == 0) if start_with_long else (k % 2 == 1)
            s = r if is_long else 2.0 * r
            y = y0 + k * sqrt3 * r
            if y + r > H:
                break
            if s > W - r + 1e-15:
                continue
            span = (W - r) - s
            ncols = int(np.floor(span / (2.0 * r) + 1.0 + 1e-12))
            for j in range(ncols):
                x = s + 2.0 * r * j
                centers.append([x, y])
                if len(centers) >= limit:
                    return np.array(centers)
        return np.array(centers)

    def poisson_packing_projection(xs, ys, W, H, max_iter=500, tol=1e-12):
        m = len(xs)
        centers = np.column_stack([xs, ys])
        # Wall constraints
        u = np.minimum.reduce([xs, ys, W - xs, H - ys])
        r = np.minimum(u, 0.5 * min(W, H))
        r = np.maximum(r, 0.0)

        # Precompute distance matrix (symmetric)
        dx = xs[:, None] - xs[None, :]
        dy = ys[:, None] - ys[None, :]
        d = np.hypot(dx, dy)
        np.fill_diagonal(d, np.inf)

        # Project using iterative relaxation: r_i <= d_ij - r_j for all j
        for _ in range(max_iter):
            r_new = np.copy(r)
            for i in range(m):
                if d[i].size == 0:
                    continue
                min_gap = np.min(d[i] - r)
                r_new[i] = min(u[i], min_gap)
            r_new = np.clip(r_new, 0.0, None)
            if np.max(np.abs(r_new - r)) <= tol:
                r = r_new
                break
            r = r_new

        # Final safety: resolve any residual violations
        for _ in range(3):
            for i in range(m):
                for j in range(i + 1, m):
                    if r[i] + r[j] - d[i, j] > 1e-10:
                        diff = r[i] + r[j] - d[i, j]
                        if r[i] >= r[j]:
                            r[i] -= min(diff, r[i])
                        else:
                            r[j] -= min(diff, r[j])
        r = np.minimum(r, u)
        r = np.maximum(r, 0.0)
        return r

    best_sum = -1.0
    best_circles = None

    # Explore a curated range of aspect ratios
    aspects = np.linspace(0.7, 1.4, 80)
    for a in aspects:
        if time.time() - start_time > time_limit:
            break
        W = 2.0 * a / (1.0 + a)
        H = 2.0 / (1.0 + a)
        if W + H > 2.001:
            continue
        for start_with_long in (True, False):
            r_base = binary_search_r(W, H, start_with_long)
            if r_base <= 1e-8:
                continue
            centers = build_hex_centers(W, H, r_base, start_with_long, limit=n)
            if len(centers) < n:
                r_base *= 0.99
                centers = build_hex_centers(W, H, r_base, start_with_long, limit=n)
                if len(centers) < n:
                    continue
            xs, ys = centers[:, 0], centers[:, 1]
            radii = poisson_packing_projection(xs, ys, W, H)
            total_radius = np.sum(radii)
            if total_radius <= best_sum:
                continue

            # Verify feasibility
            valid = True
            for i in range(n):
                if not np.isfinite(xs[i]) or not np.isfinite(ys[i]) or not np.isfinite(radii[i]):
                    valid = False
                    break
                if xs[i] - radii[i] < -1e-8 or ys[i] - radii[i] < -1e-8 or xs[i] + radii[i] > W + 1e-8 or ys[i] + radii[i] > H + 1e-8:
                    valid = False
                    break
                for j in range(i + 1, n):
                    d = np.hypot(xs[i] - xs[j], ys[i] - ys[j])
                    if radii[i] + radii[j] - d > 1e-8:
                        valid = False
                        break
                if not valid:
                    break
            if not valid:
                continue

            if total_radius > best_sum:
                best_sum = total_radius
                best_circles = np.column_stack([xs, ys, radii])

    if best_circles is None:
        # Fallback: uniform grid with small radii
        W = H = 1.0
        xs = np.linspace(0.1, 0.9, 7)
        ys = np.linspace(0.1, 0.9, 3)
        pts = []
        for y in ys:
            for x in xs:
                pts.append((x, y))
        pts = np.array(pts)[:n]
        r = np.full(n, 1e-3)
        return np.column_stack([pts[:, 0], pts[:, 1], r])

    # Final adjustment: shift to ensure non-negative bounds
    min_x = np.min(best_circles[:, 0] - best_circles[:, 2])
    min_y = np.min(best_circles[:, 1] - best_circles[:, 2])
    if min_x < 0 or min_y < 0:
        tx = max(0, -min_x + 1e-12)
        ty = max(0, -min_y + 1e-12)
        best_circles[:, 0] += tx
        best_circles[:, 1] += ty

    return best_circles
